effect.frag.content:
uniform float u_amount;
uniform float u_rate;
uniform vec4 u_tint;
uint hash(uint x) { x ^= x >> 16; x *= 2146121005u; x ^= x >> 15; x *= 2221713035u; return x ^ (x >> 16); }
void main() {
  uint state = uint(floor(u_time * u_rate));
  uint band = uint(floor(v_uv.y * 24.0));
  float r = float(hash(band + state * 1013u + uint(u_seed) * 31u) & 65535u) / 65535.0;
  vec2 uv = v_uv + vec2((r - 0.5) * u_amount, 0.0);
  vec4 c = uv.x >= 0.0 && uv.x <= 1.0 ? texture(u_source, uv) : vec4(0.0);
  c.rgb = mix(c.rgb, u_tint.rgb * c.a, step(0.7, r) * u_amount * u_tint.a);
  fragColor = c;
}
